class Slot93RawAdapterRegression(unittest.TestCase):
    def evaluate(self,record):
        return assess('normal',record['lifecycle'],record['capture'],record['independent_members'],record['independent_accounting'],record['peer_survived_terminal'])

    def test_actual_two_retained_handles_bind_without_mutating_original_observations(self):
        data=copy.deepcopy(RETAINED);before=copy.deepcopy(data)
        result=self.evaluate(data)
        self.assertEqual(result['independent_raw_trace_adapter']['state'],'independent_raw_schema_verified')
        self.assertEqual(result['independent_raw_trace_adapter']['retained_member_exit_proofs'],2)
        self.assertEqual(data,before);self.assertFalse(result['guest_qualification']);self.assertFalse(result['export_acceptance'])

    def test_root_wait_code_identity_role_and_complete_events_cannot_be_weakened(self):
        for defect in ('live','boolean_wait','nonzero','missing_exit_query','birth_reuse','role_swap','missing_child','event_missing'):
            data=copy.deepcopy(RETAINED)
            if defect=='live':data['independent_members'][0]['exit_wait_result']=258
            elif defect=='boolean_wait':data['independent_members'][0]['exit_wait_result']=False
            elif defect=='nonzero':data['independent_members'][0]['exit_code']=1
            elif defect=='missing_exit_query':del data['capture']['member_trace']['members'][0]['exit']['exit_code_query']
            elif defect=='birth_reuse':data['independent_members'][0]['identity']['creation_time_100ns']='999'
            elif defect=='role_swap':data['independent_members'].reverse()
            elif defect=='missing_child':data['capture']['member_trace']['members'].pop()
            else:data['capture']['member_trace']['collection']['events'].pop()
            with self.subTest(defect=defect),self.assertRaises((AssertionError,ValueError,KeyError)):self.evaluate(data)


if __name__=='__main__':unittest.main()
